"use client";
import React, { useRef } from "react";
import { motion, useScroll, useTransform } from "framer-motion";

export function ContainerScroll({
  children,
  titleComponent,
  containerRef,
  className = "",
}) {
  const targetRef = useRef(null);
  const containerRefToUse = containerRef || targetRef;

  const { scrollYProgress } = useScroll({
    target: containerRefToUse,
    offset: ["start start", "end end"],
  });

  // Smooth 3D transformation based on scroll
  const scale = useTransform(scrollYProgress, [0, 0.5, 1], [1, 0.85, 0.75]);
  const opacity = useTransform(scrollYProgress, [0, 0.4, 0.6], [1, 1, 0]);
  const translateY = useTransform(scrollYProgress, [0, 1], [0, -150]);
  const rotateX = useTransform(scrollYProgress, [0, 0.5, 1], [0, 8, 15]);
  const borderRadius = useTransform(scrollYProgress, [0, 1], ["0px", "24px"]);
  const translateZ = useTransform(scrollYProgress, [0, 1], [0, -100]);

  // Title animations
  const titleOpacity = useTransform(scrollYProgress, [0, 0.15, 0.4, 0.6], [0, 1, 1, 0]);
  const titleTranslateY = useTransform(scrollYProgress, [0, 0.15, 0.4, 0.6], [80, 0, 0, -50]);
  const titleScale = useTransform(scrollYProgress, [0, 0.15, 0.4, 0.6], [0.9, 1, 1, 0.95]);

  // Gradient overlay that intensifies on scroll
  const overlayOpacity = useTransform(scrollYProgress, [0, 0.5], [0, 0.1]);

  return (
    <div ref={containerRefToUse} className={`relative h-[250vh] ${className}`}>
      <div className="sticky top-0 h-screen overflow-hidden">
        {/* Background gradient that appears on scroll */}
        <motion.div
          style={{ opacity: overlayOpacity }}
          className="absolute inset-0"
          style={{
            background: "linear-gradient(180deg, rgba(212,175,55,0.05) 0%, rgba(255,255,255,0) 50%)",
            opacity: overlayOpacity,
          }}
        />

        {/* Main Content Container with 3D transform */}
        <motion.div
          style={{
            scale,
            opacity,
            rotateX,
            translateY,
            translateZ,
            borderRadius,
            perspective: 1200,
            transformStyle: "preserve-3d",
          }}
          className="relative w-full h-full bg-white shadow-2xl will-change-transform"
        >
          {/* Gold accent border top */}
          <motion.div
            className="absolute top-0 left-0 w-full h-1 z-20"
            style={{
              background: "linear-gradient(90deg, transparent, #d4af37, #f4d77a, #d4af37, transparent)",
              opacity: useTransform(scrollYProgress, [0, 0.3], [1, 0]),
            }}
          />

          {/* Gold border bottom that appears */}
          <motion.div
            className="absolute bottom-0 left-0 w-full h-1 z-20"
            style={{
              background: "linear-gradient(90deg, transparent, #d4af37, #f4d77a, #d4af37, transparent)",
              opacity: useTransform(scrollYProgress, [0.3, 0.7], [0, 1]),
            }}
          />

          {children}
        </motion.div>

        {/* Title Component - smooth fade in/out */}
        <motion.div
          style={{
            opacity: titleOpacity,
            translateY: titleTranslateY,
            scale: titleScale,
          }}
          className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none z-10"
        >
          <div className="max-w-4xl px-8">
            {titleComponent}
          </div>
        </motion.div>

        {/* Scroll Indicator - bouncy animation */}
        <motion.div
          style={{
            opacity: useTransform(scrollYProgress, [0, 0.15, 0.25], [1, 1, 0]),
          }}
          className="absolute bottom-8 left-1/2 -translate-x-1/2 flex flex-col items-center z-20"
        >
          <span
            className="text-xs tracking-[0.3em] uppercase mb-3"
            style={{ color: "#d4af37" }}
          >
            Scroll to explore
          </span>
          <motion.div
            animate={{
              y: [0, 8, 0],
              opacity: [1, 0.5, 1]
            }}
            transition={{
              duration: 1.5,
              repeat: Infinity,
              ease: "easeInOut"
            }}
          >
            <svg
              width="24"
              height="24"
              viewBox="0 0 24 24"
              fill="none"
              stroke="#d4af37"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <path d="M12 5v14M19 12l-7 7-7-7" />
            </svg>
          </motion.div>
        </motion.div>

        {/* Decorative corner elements */}
        <motion.div
          className="absolute top-6 left-6 w-12 h-12 border-l-2 border-t-2"
          style={{
            borderColor: "#d4af37",
            opacity: useTransform(scrollYProgress, [0, 0.2], [0.5, 0]),
          }}
        />
        <motion.div
          className="absolute top-6 right-6 w-12 h-12 border-r-2 border-t-2"
          style={{
            borderColor: "#d4af37",
            opacity: useTransform(scrollYProgress, [0, 0.2], [0.5, 0]),
          }}
        />
        <motion.div
          className="absolute bottom-6 left-6 w-12 h-12 border-l-2 border-b-2"
          style={{
            borderColor: "#d4af37",
            opacity: useTransform(scrollYProgress, [0.3, 0.5], [0, 0.5]),
          }}
        />
        <motion.div
          className="absolute bottom-6 right-6 w-12 h-12 border-r-2 border-b-2"
          style={{
            borderColor: "#d4af37",
            opacity: useTransform(scrollYProgress, [0.3, 0.5], [0, 0.5]),
          }}
        />
      </div>
    </div>
  );
}

// Standalone version without sticky container
export function ScrollRevealSection({
  children,
  className = "",
  animationType = "scale", // "scale", "slide", "fade"
}) {
  const ref = useRef(null);
  const { scrollYProgress } = useScroll({
    target: ref,
    offset: ["start end", "end start"],
  });

  const getAnimationStyle = () => {
    switch (animationType) {
      case "scale":
        return {
          scale: useTransform(scrollYProgress, [0, 0.2, 0.8, 1], [0.8, 1, 1, 0.8]),
          opacity: useTransform(scrollYProgress, [0, 0.2, 0.8, 1], [0, 1, 1, 0]),
        };
      case "slide":
        return {
          translateY: useTransform(scrollYProgress, [0, 0.2, 0.8, 1], [100, 0, 0, -100]),
          opacity: useTransform(scrollYProgress, [0, 0.2, 0.8, 1], [0, 1, 1, 0]),
        };
      case "fade":
      default:
        return {
          opacity: useTransform(scrollYProgress, [0, 0.2, 0.8, 1], [0, 1, 1, 0]),
        };
    }
  };

  const style = getAnimationStyle();

  return (
    <motion.div
      ref={ref}
      style={{
        scale: style.scale,
        opacity: style.opacity,
        translateY: style.translateY,
      }}
      className={className}
    >
      {children}
    </motion.div>
  );
}

// Parallax image component
export function ParallaxImage({
  src,
  alt,
  className = "",
  speed = 0.5,
}) {
  const ref = useRef(null);
  const { scrollYProgress } = useScroll({
    target: ref,
    offset: ["start end", "end start"],
  });

  const y = useTransform(scrollYProgress, [0, 1], [100 * speed, -100 * speed]);

  return (
    <div ref={ref} className={`overflow-hidden ${className}`}>
      <motion.img
        src={src}
        alt={alt}
        style={{ y }}
        className="w-full h-full object-cover"
      />
    </div>
  );
}
